PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS telephony_calls(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,actor_id TEXT NOT NULL,destination TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('internal','external')),state TEXT NOT NULL CHECK(state IN ('authorized','ringing','answered','media_verifying','connected','ended','failed')),carrier_id TEXT,gateway_call_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,connected_at TEXT,ended_at TEXT,version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS telephony_idempotency(tenant_id TEXT NOT NULL,actor_id TEXT NOT NULL,key TEXT NOT NULL,request_hash TEXT NOT NULL,call_id TEXT NOT NULL REFERENCES telephony_calls(id),PRIMARY KEY(tenant_id,actor_id,key));
CREATE TABLE IF NOT EXISTS telephony_events(id INTEGER PRIMARY KEY AUTOINCREMENT,call_id TEXT NOT NULL REFERENCES telephony_calls(id),event_type TEXT NOT NULL,payload TEXT NOT NULL DEFAULT '{}',occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,event_key TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS telephony_outbox(id INTEGER PRIMARY KEY AUTOINCREMENT,call_id TEXT NOT NULL REFERENCES telephony_calls(id),topic TEXT NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,delivered_at TEXT,attempts INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS telephony_usage(call_id TEXT PRIMARY KEY REFERENCES telephony_calls(id),tenant_id TEXT NOT NULL,billable_seconds INTEGER NOT NULL CHECK(billable_seconds>=0),amount_minor INTEGER NOT NULL CHECK(amount_minor>=0),currency TEXT NOT NULL,rated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS telephony_ledger(id INTEGER PRIMARY KEY AUTOINCREMENT,tenant_id TEXT NOT NULL,call_id TEXT NOT NULL REFERENCES telephony_calls(id),entry_type TEXT NOT NULL,amount_minor INTEGER NOT NULL,currency TEXT NOT NULL,event_key TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS telephony_gateway_events(event_id TEXT PRIMARY KEY,call_id TEXT NOT NULL REFERENCES telephony_calls(id),gateway_id TEXT NOT NULL,sequence_no INTEGER NOT NULL,event_type TEXT NOT NULL,payload TEXT NOT NULL,received_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(gateway_id,call_id,sequence_no));
CREATE TABLE IF NOT EXISTS telephony_meet_admissions(call_id TEXT PRIMARY KEY REFERENCES telephony_calls(id),meeting_id TEXT NOT NULL,approval_state TEXT NOT NULL CHECK(approval_state IN ('pending','approved','denied','removed')),approved_by TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS telephony_outbox_delivery(outbox_id INTEGER PRIMARY KEY REFERENCES telephony_outbox(id),lease_owner TEXT,lease_until TEXT,next_attempt_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_error TEXT,dead_lettered_at TEXT);
CREATE TABLE IF NOT EXISTS telephony_carrier_cdr(carrier_id TEXT NOT NULL,external_cdr_id TEXT NOT NULL,call_id TEXT NOT NULL REFERENCES telephony_calls(id),seconds INTEGER NOT NULL CHECK(seconds>=0),amount_minor INTEGER NOT NULL CHECK(amount_minor>=0),currency TEXT NOT NULL,raw_hash TEXT NOT NULL,received_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(carrier_id,external_cdr_id));
CREATE TABLE IF NOT EXISTS telephony_reconciliation(call_id TEXT PRIMARY KEY REFERENCES telephony_calls(id),status TEXT NOT NULL CHECK(status IN ('matched','disputed','pending')),difference_minor INTEGER NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS telephony_gateway_heartbeat(gateway_id TEXT PRIMARY KEY,last_seen TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,version TEXT NOT NULL,capacity INTEGER NOT NULL CHECK(capacity>=0));
